const pruneExpiredCeremonies = `-- name: PruneExpiredCeremonies :execrows
DELETE FROM auth_ceremony
WHERE id IN (
    SELECT c.id FROM auth_ceremony c
    WHERE c.expires_at < now()
    LIMIT 20
)
`

// Called on every new ceremony, so the table stays bounded by the rate of
// ceremonies times their lifetime without a separate job.
func (q *Queries) PruneExpiredCeremonies(ctx context.Context) (int64, error) {
	result, err := q.db.Exec(ctx, pruneExpiredCeremonies)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

